import"./chunk-2NFLSA4Y.js";var t={fluidFlow:{theory:{concept:"[[Continuity equation: in a steady flow of an incompressible liquid, the same volume passes through every cross-section of a pipe each second, A\u2081v\u2081 = A\u2082v\u2082.]] So the liquid moves faster where the pipe is narrower. Bernoulli's law adds the energy side: along a streamline of an ideal liquid p + \xBD\u03C1v\xB2 + \u03C1gh stays constant, so in a horizontal pipe the static pressure is lower where the speed is higher."},section:{continuity:{title:"The same flow through each section",text:"[[Q = Av is the volume passing per second.]] If the radius is halved, area becomes one quarter and speed becomes four times larger. Widening the middle section slows the liquid."},bernoulli:{title:"Energy along the flow",text:"Bernoulli\u2019s equation balances static pressure, kinetic energy per unit volume and gravitational potential energy per unit volume. The horizontal pipe has equal height everywhere, so its height term cancels. Pressure recovers when the pipe returns to its original area."},pressure:{title:"Static pressure and speed",text:"The readings show absolute static pressure, not pressure relative to the atmosphere. A positive p\u2081\u2212p\u2082 means the middle has lower pressure; a negative value means higher pressure. The pressure difference is proportional to density and to the difference of squared speeds."},boundary:{title:"What controls the flow here?",text:"An ideal external supply maintains the selected inlet speed and pressure. Changing the inlet pressure shifts all static pressures; it does not change the speed imposed by the supply. This is not a pump or reservoir model."},real:{title:"Where the ideal picture stops",text:"[[Real pipes have friction, turbulence and pressure losses, especially through constrictions.]] Their outlet pressure generally does not fully recover. Very low absolute pressure can cause cavitation; the available controls keep this model well away from that situation."}},param:{ratio:"Middle radius / inlet radius",speed:"Inlet speed",density:"Liquid density",pressure:"Inlet absolute pressure",radius:"Inlet radius",timeStep:"Time step"},hint:{ratio:"This is a radius ratio, not an area ratio. Below 1 narrows the middle; above 1 widens it.",speed:"An ideal source maintains this speed. Faster inlet flow produces a larger pressure difference.",pressure:"Absolute pressure: vacuum is 0 kPa. It shifts pressure readings without changing the imposed speed.",radius:"Changing the radius at a fixed radius ratio keeps the speed ratio, but changes the volume flow."},preset:{narrow:"Half-radius middle",uniform:"Uniform pipe",wide:"Wider middle",water:"Water \xB7 1000 kg/m\xB3",light:"Light liquid \xB7 800 kg/m\xB3"},measure:{speed1:"Inlet speed",speed2:"Middle speed",drop:"Pressure difference (inlet \u2212 middle)",pressure2:"Middle absolute pressure",flow:"Volume flow rate",volume:"Volume passed through the inlet",area1:"Inlet cross-sectional area",area2:"Middle cross-sectional area",total:"Total pressure (static + dynamic)"},graph:{volume:"Passed volume over time",speed:"Section speeds over time (steady flow)"},view:{inlet:"1 \xB7 Inlet: {value}",throat:"2 \xB7 Middle: {value}",outlet:"3 \xB7 Outlet: {value}",speed1:"v\u2081 = {value}",speed2:"v\u2082 = {value}",scale:"Schematic 3D pipe \xB7 radial size exaggerated",markers:"Moving liquid markers",sections:"Measurement sections",vectors:"Velocity arrows"},formula:{continuity:"Continuity of incompressible flow",area:"Circular cross-sectional area",bernoulli:"Bernoulli\u2019s equation along a streamline",horizontal:"Equal-height pressure relation"},variable:{area:"Cross-sectional area",speed:"Section-average speed",pressure:"Absolute static pressure",height:"Height above a reference level",gravity:"Gravitational acceleration"},assumption:{ideal:"Steady incompressible flow without viscosity, turbulence, energy losses or compressibility.",horizontal:"A horizontal pipe: all measurement sections have equal height, so gravitational terms cancel.",boundary:"An ideal external source maintains the selected inlet speed and absolute pressure. Pump behaviour and pressure-driven flow startup are not calculated.",section:"The model uses uniform section-average axial speed and a smoothly changing area. It is a one-dimensional approximation, not a 3D fluid simulation.",drawing:"The pipe is 1 m long in the model. Its radial dimensions are enlarged relative to length for readability; particles, arrows and section markers are not to scale.",markers:"Dots are schematic tracers, not molecules. Axial motion follows Q/A at fixed timesteps; radial placement represents streamlines schematically. Dots reappear at the inlet after leaving, without recirculating the modeled liquid."},challenge:{fast:{title:"Four times faster",description:"Make the middle speed at least four times the inlet speed.",hint:"A radius one half as large gives an area one quarter as large."},equal:{title:"Equal speeds and pressures",description:"Make section speeds equal and the pressure difference zero.",hint:"Try the same radius throughout the pipe."},recover:{title:"Raise the middle pressure",description:"Make middle static pressure exceed inlet pressure by more than 0.1 kPa.",hint:"Widen the middle to slow the liquid."},drop:{title:"A 10 kPa difference",description:"Make inlet pressure exceed middle pressure by at least 10 kPa.",hint:"Narrow the middle and increase inlet speed."},volume:{title:"Pass 20 litres",description:"Let at least 20 litres flow through the inlet.",hint:"Start the flow and watch the volume reading; greater inlet speed passes more per second."}}}},i={sim:t};export{i as default,t as sim};
